contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address attacker, address _owner) public {
        require(attacker != address(this));

        address before = c.owner();

        bool reverted;
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("setOwner(address)", _owner)
        );
        reverted = !ok;

        address after = c.owner();

        assert(reverted && after == before);
    }

    receive() external payable {}
}

