    C c;
    constructor(C _c) { c = _c; }

    function run(address attacker, address _owner) public {
        require(attacker != address(this));
        require(attacker != address(0));

        address before = c.owner();

        vm.prank(attacker);
        bool reverted;
        try c.setOwner(_owner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address currentOwner = c.owner();

        assert(reverted && currentOwner == before);
    }

    receive() external payable {}
}

